40	const estimateWrappedTextHeight = (content: string, columnWidth: number): number => {
41	  const textWidth = Math.max(1, columnWidth - CONTENT_HORIZONTAL_PADDING);
42	  const charsPerLine = Math.max(CONTENT_MIN_CHARS_PER_LINE, Math.floor(textWidth / CONTENT_AVERAGE_CHAR_WIDTH));
43	  const lineCount = content.split("\n").reduce((total, line) => total + Math.max(1, Math.ceil(line.length / charsPerLine)), 0);
44	  return lineCount * CONTENT_LINE_HEIGHT;
45	};
46	
47	const countMarkdownImages = (content: string): number => {
48	  const markdownImages = content.match(/!\[[^\]]*]\([^)]+\)/g)?.length ?? 0;
49	  const htmlImages = content.match(/<img\s/gi)?.length ?? 0;
50	  return markdownImages + htmlImages;
51	};
52	
53	const isVisualAttachment = (attachment: Attachment): boolean => {
54	  const type = getAttachmentType(attachment);
55	  return type === "image/*" || type === "video/*" || isMotionAttachment(attachment);
56	};
57	
58	const isAudioAttachment = (attachment: Attachment): boolean => getAttachmentType(attachment) === "audio/*";
59	
60	const estimateVisualGalleryHeight = (visualAttachments: Attachment[], columnWidth: number): number => {
61	  const count = buildAttachmentVisualItems(visualAttachments).length;
62	  if (count === 0) return 0;
63	  if (count === 1) {
64	    const type = getAttachmentType(visualAttachments[0]!);
65	    return type === "video/*" ? Math.round(columnWidth * SINGLE_VIDEO_ASPECT_RATIO) : SINGLE_IMAGE_HEIGHT;
66	  }
67	  if (count === 2) return TWO_VISUAL_ITEMS_HEIGHT;
68	  if (count <= 4) return MOSAIC_VISUAL_ITEMS_HEIGHT;
69	  return SIX_VISUAL_ITEMS_HEIGHT;
70	};
