89	const countCommentRelations = (memo: Memo): number =>
90	  (memo.relations ?? []).filter((relation) => relation.type === MemoRelation_Type.COMMENT && relation.relatedMemo?.name === memo.name)
91	    .length;
92	
93	const estimateCommentPreviewHeight = (memo: Memo): number => {
94	  const visibleCommentCount = Math.min(countCommentRelations(memo), MAX_VISIBLE_COMMENT_PREVIEWS);
95	  if (visibleCommentCount === 0) return 0;
96	  return COMMENT_PREVIEW_VERTICAL_PADDING + COMMENT_PREVIEW_HEADER_HEIGHT + visibleCommentCount * COMMENT_PREVIEW_ROW_HEIGHT;
97	};
